// ===========================================================================
// Фикстура смены размера кадра (§40, tests/agent/renderer_resize_test.py).
//
// Сцена нарочно простая и с известными числами — по ней видно, что кадр
// пересобрался, а камера не «уехала»:
//   * фон мира #14202c — кадр не чёрный при любом размере;
//   * маркер 64x64 в точке камеры (160,120): его центр обязан оставаться
//     центром кадра, каким бы ни был размер (камера смотрит в ту же точку);
//   * проба 32x32 со смещением +100 по X: её экранная позиция обязана быть
//     (w/2+100, h/2) — так проверяется, что worldToScreen следует за новым
//     размером, а не за прежним.
//
// Камера и мир: зум 1, поворот 0 — мировые координаты совпадают с экранными
// при камере в центре. Никаких bounds: ограничение камеры не должно влиять на
// проверку «камера не уезжает».
// ===========================================================================
$.ready(() => {
    $.world.gravity(0, 0).color('#14202c');
    $.camera.at(160, 120).zoom(1);

    $('<rect>', { id: 'marker' }).at(160, 120).size(64, 64)
        .color('#e0b040').appendTo($.world);
    $('<rect>', { id: 'probe' }).at(260, 120).size(32, 32)
        .color('#40e0b0').appendTo($.world);

    $.fixture = {
        /** Опорные точки сцены: тест берёт их здесь, а не из своих констант. */
        anchor() {
            return {
                camera: { x: 160, y: 120 },
                zoom: 1,
                // Проба смещена на +100 по X от камеры.
                probe: { x: 260, y: 120, offset: 100 },
                colors: { bg: [20, 32, 44], marker: [224, 176, 64], probe: [64, 224, 176] },
            };
        },
    };
});
